    if (!state.active || state.busy || state.paused) return;
    lane = ((lane % 4) + 4) % 4;
    const t = Math.max(20, time() + 20);
    if (lane === state.lane || t <= lastSaved || (moves.length && t < moves[moves.length - 1].t + 100)) return;
    if (moves.length >= 9000) { finish(); return; }
